import app from "@/store/app";
import { Button, Empty, Tooltip, Trigger, Typography } from "@arco-design/web-react";
import React, { useState } from "react";
import { SketchPicker } from 'react-color';
import { generate, getRgbStr } from '@arco-design/color';
import useLocale from '@/utils/useLocale';
import IconButton from "@/components/NavBar/IconButton";
import styles from '../style/color-panel.module.less';
import { IconMoonFill, IconSunFill } from "@arco-design/web-react/icon";
import store from './store';
import theme from "@/store/theme";
import { useObserver } from "mobx-react-lite";
import { IfrmaeWindowProps } from "@/types/iframe";


const ThemeCard = ({ name, des, colors, used, onUse }) => {
    return (
        <div className="p-4 bg-gray-100 rounded-lg shadow-lg relative">
            {used && (
                <div className="absolute top-0 right-0 bg-green-500 text-white px-2 py-1 rounded-bl-lg rounded-tr-lg">
                    当前主题
                </div>
            )}
            <h2 className="text-xl font-semibold mb-2">{name}</h2>
            <p className="text-gray-600 mb-4">{des}</p>
            <div className="flex justify-center items-center">
                {Object.values(colors).map((color, index) => (
                    <div
                        key={index}
                        className="w-8 h-8 rounded-md shadow-md mx-1"
                        style={{ backgroundColor: `${color}` }}
                    ></div>
                ))}
            </div>
            <button
                className="mt-4 py-2 px-4 bg-blue-500 text-white rounded hover:bg-blue-600 transition-colors"
                onClick={onUse}
            >
                使用
            </button>
        </div>
    );
};

const ThemeGallery = ({ colorSchemes, usedTheme, onUseTheme }) => {
    return (
        <div className="container mx-auto">
            <h1 className="text-3xl font-semibold mb-4">Color Themes Gallery</h1>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {colorSchemes.map((theme, index) => (
                    <ThemeCard
                        key={index}
                        name={theme.name}
                        des={theme.des}
                        colors={theme.colors}
                        used={usedTheme === theme.name}
                        onUse={() => onUseTheme(theme)}
                    />
                ))}
            </div>
        </div>
    );
};



const AppTheme = () => {
    const t = useLocale();

    const win:IfrmaeWindowProps = window as any;
    
    // if(win.theme){
    //     // 如果数据不一致，需要同步
    //     if(win.theme.themeColor != theme.themeColor){
    //         theme.setThemeColor(win.theme.themeColor);
    //     }
    //     if(win.theme.theme !== theme.theme){
    //         theme.setTheme(win.theme.theme);
    //     }
    // }

    return useObserver(() => {

        const themeColor = theme.themeColor || "#165DFF";
        // console.log('theme', theme.themeColor, theme)
        const list = generate(themeColor, { list: true });

        return (
            <React.Fragment>
                <div style={{ width: 280 }}>
                <Tooltip
                    content={
                        theme.theme !== 'dark'
                            ? t['settings.navbar.theme.toDark']
                            : t['settings.navbar.theme.toLight']
                    }
                >
                    <Button
                        shape="round"
                        style={{ marginBottom: 10 }}
                        icon={theme.theme == 'dark' ? <IconMoonFill /> : <IconSunFill />}
                        onClick={() => {
                            if(win.theme) win.theme.setTheme(theme.theme == 'light'? 'dark' : 'light');
                            theme.setTheme(theme.theme == 'light'? 'dark' : 'light');
                        }}
                    >
                        {theme.theme === "dark"? "暗色模式" : "亮色模式"}
                    </Button>
                </Tooltip>
                    <Trigger
                        trigger="hover"
                        position="bl"
                        popup={() => (
                            <SketchPicker
                                color={themeColor}
                                onChangeComplete={(color) => {
                                    if(win.theme) win.theme.setThemeColor(color.hex);
                                    theme.setThemeColor(color.hex);
                                }}
                            />
                        )}
                    >
                        <div className={styles.input}>
                            <div
                                className={styles.color}
                                style={{ backgroundColor: themeColor }}
                            />
                            <span>{themeColor}</span>
                        </div>
                        <ul className={styles.ul}>
                            {list.map((item, index) => (
                                <li
                                    key={index}
                                    className={styles.li}
                                    style={{ backgroundColor: item }}
                                />
                            ))}
                        </ul>
                    </Trigger>
                </div>
                <ThemeGallery
                    colorSchemes={store.colorSchemes}
                    usedTheme={theme.config? theme.config.name : "Classic"}
                    onUseTheme={(config) => {
                        if(config.name === "Classic"){
                            theme.setConfig();
                        }else {
                            theme.setConfig(config);
                        }
                    }}
                />
            </React.Fragment>
        )
    })

}

export default AppTheme;